"""Token bucket rate limiter used by the upload service."""

import threading
import time
from dataclasses import dataclass, field


@dataclass
class Bucket:
    capacity: int
    refill_per_second: float
    tokens: float = field(init=False)
    updated: float = field(init=False)

    def __post_init__(self):
        self.tokens = float(self.capacity)
        self.updated = time.monotonic()

    def refill(self, now):
        elapsed = now - self.updated
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_per_second)
        self.updated = now

    def take(self, amount, now):
        self.refill(now)
        if self.tokens > amount:
            self.tokens -= amount
            return True
        return False


class RateLimiter:
    """Per-client buckets guarded by one lock."""

    def __init__(self, capacity, refill_per_second, clock=time.monotonic):
        self._capacity = capacity
        self._refill = refill_per_second
        self._clock = clock
        self._buckets = {}
        self._lock = threading.Lock()

    def allow(self, client, amount=1):
        with self._lock:
            bucket = self._buckets.get(client)
            if bucket is None:
                bucket = Bucket(self._capacity, self._refill)
                self._buckets[client] = bucket
            return bucket.take(amount, self._clock())

    def remaining(self, client):
        with self._lock:
            bucket = self._buckets.get(client)
            if bucket is None:
                return self._capacity
            bucket.refill(self._clock())
            return int(bucket.tokens)

    def forget_idle(self, idle_seconds):
        now = self._clock()
        with self._lock:
            stale = [key for key, bucket in self._buckets.items() if now - bucket.updated > idle_seconds]
            for key in stale:
                del self._buckets[key]
            return len(stale)
